-- ============================================================
-- Ecosystem - development seed data
--
-- Mirrors lib/data/demo_bins.dart and lib/screens/demo_data.dart so the
-- database and the Flutter demo mode show the same network.
--
-- Run AFTER schema.sql:   psql -d ecosystem -f seed.sql
--
-- Every insert is idempotent (ON CONFLICT DO NOTHING) and every UUID is
-- fixed, so re-running this never duplicates rows.
--
-- Passwords are deliberately NULL. Seed accounts cannot be logged into
-- until a real Argon2id hash is generated by the (not yet written) auth
-- service. Do not commit a working password hash to a shared database.
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- Users
-- ------------------------------------------------------------

