VALUES
    ('00000000-0000-4000-8000-000000000001', 'System',    'Admin',   '+233200000001', U&'\+01F6E1\FE0F', 'admin',      'none', NULL, NULL, NULL),
    ('00000000-0000-4000-8000-000000000002', 'Ama Boateng', 'Ama',   '+233200000002', U&'\+01F333', 'ambassador', 'approved', 'Market Square', 'Wanted to keep the market clean on collection days.', now() - interval '60 days'),
    ('00000000-0000-4000-8000-000000000003', 'Kofi Mensah', 'Kofi',  '+233200000003', U&'\+01F6B2', 'ambassador', 'approved', 'North Campus',  'Students near the hostels were overflowing bins weekly.', now() - interval '45 days'),
    ('00000000-0000-4000-8000-000000000010', 'Kwame Owusu',  'Kweku',  '+233200000010', U&'26BD', 'user',       'none', NULL, NULL, NULL),
    ('00000000-0000-4000-8000-000000000011', 'Abena Sarpong','Abena',  '+233200000011', U&'\+01F4DA', 'user',       'none', NULL, NULL, NULL),
    ('00000000-0000-4000-8000-000000000012', 'Yaw Darko',    'Yaw',    '+233200000012', U&'\+01F3A7', 'user',       'pending', 'Ring Road East', 'I see the junction bins fill up every weekend.', now() - interval '2 days')
ON CONFLICT (id) DO NOTHING;

