-- BIN-001..BIN-006 match demo_bins.dart exactly, including the
-- created_by ids that were missing there (demo mode showed "my bins: 0").
-- ------------------------------------------------------------

INSERT INTO bins (id, code, name, bin_state, status_source, fill_percent, capacity_kg, address, latitude, longitude, sensor_id, created_by_id, created_by_role)
VALUES
    ('10000000-0000-4000-8000-000000000001', 'BIN-001', 'Campus Main Gate',  'available', 'sensor',  22.00, 120, 'Main Gate, University Road',        5.6042000, -0.1875000, 'SNS-1001', '00000000-0000-4000-8000-000000000001', 'admin'),
    ('10000000-0000-4000-8000-000000000002', 'BIN-002', 'Library Car Park',  'filling',   'sensor',  64.00, 120, 'Library Car Park, Block C',          5.6071000, -0.1841000, 'SNS-1002', '00000000-0000-4000-8000-000000000001', 'admin'),
    ('10000000-0000-4000-8000-000000000003', 'BIN-003', 'Market Square',     'full',      'sensor',  98.00,  80, 'Market Square, Central',             5.5998000, -0.1908000, 'SNS-1003', '00000000-0000-4000-8000-000000000002', 'ambassador'),
    ('10000000-0000-4000-8000-000000000004', 'BIN-004', 'Hostel Block A',    'available', 'manual',  31.00, 120, 'Hostel Block A, North Campus',       5.6092000, -0.1921000, NULL,       '00000000-0000-4000-8000-000000000003', 'ambassador'),
    ('10000000-0000-4000-8000-000000000005', 'BIN-005', 'Junction Traffic',  'full',      'manual', 100.00, 120, 'Junction, Ring Road East',           5.5956000, -0.1838000, NULL,       '00000000-0000-4000-8000-000000000002', 'ambassador'),
    ('10000000-0000-4000-8000-000000000006', 'BIN-006', 'Community Centre',  'disabled',  'sensor',  45.00,  60, 'Community Centre, West',             5.6117000, -0.1855000, 'SNS-1006', '00000000-0000-4000-8000-000000000001', 'admin')
ON CONFLICT (id) DO NOTHING;

ALTER SEQUENCE bin_code_seq RESTART WITH 7;

UPDATE bins
SET notes = 'Lid hinge replaced, awaiting re-test.'
WHERE id = '10000000-0000-4000-8000-000000000006'
  AND notes IS DISTINCT FROM 'Lid hinge replaced, awaiting re-test.';

-- Backfill the history table so bin_status_events is not empty on a fresh
-- database. Seeded directly rather than via UPDATE, because the
-- bins_log_state_change trigger only fires on UPDATE.
INSERT INTO bin_status_events (bin_id, previous_state, new_state, fill_percent, source, reported_by_id, note)
SELECT
    id,
    NULL,
    bin_state,
    fill_percent,
    status_source,
    created_by_id,
    'Imported from legacy Firebase collection'
FROM bins
WHERE NOT EXISTS (
    SELECT 1 FROM bin_status_events e WHERE e.bin_id = bins.id
);

